adcs_quat_t q_cur, q_tgt, q_rel, q_cmd;
adcs_vec3_t axis;
double angle, sin_half, braking, target_rate, delta, step;
double prev_rate;
int valid = 1;
int reversal = 0;
double axis_norm;

qs_output.reversal_reset = 0;
qs_output.command_q_bi = (adcs_quat_t){1, 0, 0, 0};
qs_output.error_angle_rad = 0.0;
qs_output.applied_step_rad = 0.0;
qs_output.commanded_rate_rad_cycle = 0.0;
qs_output.braking_rate_rad_cycle = 0.0;
qs_output.slew_axis = (adcs_vec3_t){0, 0, 0};

/* Validate pointers */
if ((qs_input.current_q_bi == NULL) || (qs_input.target_q_bi == NULL)) {
    qs_state.mode = QS_FAULT;
    qs_state.settled = 0;
    qs_output.mode = QS_FAULT;
    qs_output.settled = 0;
    return;
}

/* Validate configuration */
if (!(isfinite(qs_config.max_rate_rad_cycle) && qs_config.max_rate_rad_cycle > 0.0 &&
      qs_config.max_rate_rad_cycle <= ADCS_PI) ||
    !(isfinite(qs_config.max_accel_rad_cycle2) && qs_config.max_accel_rad_cycle2 > 0.0) ||
    !(isfinite(qs_config.settle_rate_rad_cycle) && qs_config.settle_rate_rad_cycle >= 0.0 &&
      qs_config.settle_rate_rad_cycle <= qs_config.max_rate_rad_cycle) ||
    !(isfinite(qs_config.settle_angle_rad) && qs_config.settle_angle_rad >= 0.0 &&
      qs_config.settle_angle_rad <= qs_config.max_rate_rad_cycle) ||
    (qs_config.settle_cycles < 1U) || (qs_config.settle_cycles > 20U)) {
    qs_state.mode = QS_FAULT;
    qs_state.settled = 0;
    qs_output.mode = QS_FAULT;
    qs_output.settled = 0;
    return;
}

/* Disable resets HOLD and all profile history */
if (!qs_input.enable) {
    qs_state.mode = QS_HOLD;
    qs_state.settled = 0;
    qs_state.commanded_rate_rad_cycle = 0.0;
    qs_state.axis_valid = 0;
    qs_state.previous_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.mode = QS_HOLD;
    qs_output.settled = 0;
    qs_output.command_q_bi = *qs_input.current_q_bi;
    return;
}

/* Normalize current and target */
if (adcs_quat_normalize(qs_input.current_q_bi, &q_cur) != ADCS_OK) {
    valid = 0;
}
if (adcs_quat_normalize(qs_input.target_q_bi, &q_tgt) != ADCS_OK) {
    valid = 0;
}
if (!valid) {
    qs_state.mode = QS_FAULT;
    qs_state.settled = 0;
    qs_output.mode = QS_FAULT;
    qs_output.settled = 0;
    return;
}

/* relative = target * conjugate(current) */
{
    adcs_quat_t conj = adcs_quat_conjugate(&q_cur);
    q_rel = adcs_quat_multiply(&q_tgt, &conj);
}
/* shortest sign */
if (q_rel.w < 0.0) {
    q_rel.w = -q_rel.w;
    q_rel.x = -q_rel.x;
    q_rel.y = -q_rel.y;
    q_rel.z = -q_rel.z;
}

/* principal angle and rotation axis */
{
    double w = q_rel.w;
    double s2;
    if (w > 1.0) w = 1.0;
    if (w < -1.0) w = -1.0;
    angle = 2.0 * acos(w);
    s2 = sqrt(1.0 - w * w);
    if (s2 > ADCS_EPS_QUAT) {
        axis = (adcs_vec3_t){q_rel.x / s2, q_rel.y / s2, q_rel.z / s2};
    } else {
        axis = (adcs_vec3_t){0, 0, 0};
    }
}

/* braking envelope */
braking = sqrt(2.0 * qs_config.max_accel_rad_cycle2 * angle);
target_rate = braking;
if (target_rate > qs_config.max_rate_rad_cycle) {
    target_rate = qs_config.max_rate_rad_cycle;
}
if (target_rate < 0.0) {
    target_rate = 0.0;
}

/* reversal reset check */
if (qs_state.axis_valid &&
    adcs_vec3_dot(&qs_state.previous_axis, &axis) < 0.0) {
    qs_state.commanded_rate_rad_cycle = 0.0;
    reversal = 1;
    qs_output.reversal_reset = 1;
}

/* Move stored rate toward target by at most accel */
prev_rate = qs_state.commanded_rate_rad_cycle;
delta = target_rate - prev_rate;
if (delta > qs_config.max_accel_rad_cycle2) {
    delta = qs_config.max_accel_rad_cycle2;
} else if (delta < -qs_config.max_accel_rad_cycle2) {
    delta = -qs_config.max_accel_rad_cycle2;
}
qs_state.commanded_rate_rad_cycle = prev_rate + delta;
if (qs_state.commanded_rate_rad_cycle < 0.0) {
    qs_state.commanded_rate_rad_cycle = 0.0;
}

/* apply min(rate, angle) */
step = qs_state.commanded_rate_rad_cycle;
if (step > angle) {
    step = angle;
}
if (step < 0.0) {
    step = 0.0;
}

/* store last nonzero slew axis */
axis_norm = sqrt(axis.x * axis.x + axis.y * axis.y + axis.z * axis.z);
if (axis_norm > ADCS_EPS_QUAT) {
    qs_state.previous_axis = axis;
    qs_state.axis_valid = 1;
}

/* mode determination */
{
    double rate_new = qs_state.commanded_rate_rad_cycle;
    if (rate_new >= qs_config.max_rate_rad_cycle) {
        qs_state.mode = QS_CRUISE;
    } else if (rate_new > prev_rate) {
        qs_state.mode = QS_ACCEL;
    } else if (rate_new < prev_rate) {
        qs_state.mode = QS_DECEL;
    } else {
        qs_state.mode = QS_DECEL;
    }
    if (angle <= 0.0) {
        qs_state.mode = QS_HOLD;
    }
}

/* settle logic */
if (angle <= qs_config.settle_angle_rad &&
    qs_state.commanded_rate_rad_cycle <= qs_config.settle_rate_rad_cycle) {
    if (qs_state.settled < qs_config.settle_cycles) {
        qs_state.settled++;
    }
    if (qs_state.settled >= qs_config.settle_cycles) {
        qs_state.mode = QS_HOLD;
    } else {
        qs_state.mode = QS_SETTLE;
    }
} else {
    qs_state.settled = 0;
}

/* command quaternion */
if (angle > ADCS_EPS_QUAT && step > 0.0) {
    double half = 0.5 * step;
    double sh = sin(half);
    adcs_quat_t dq = (adcs_quat_t){cos(half), axis.x * sh, axis.y * sh, axis.z * sh};
    adcs_quat_t q_tmp;
    adcs_quat_t q_prod;
    adcs_quat_normalize(&q_cur, &q_tmp);
    q_prod = adcs_quat_multiply(&dq, &q_tmp);
    adcs_quat_normalize(&q_prod, &q_cmd);
} else {
    adcs_quat_normalize(&q_cur, &q_cmd);
}

/* outputs */
qs_output.mode = qs_state.mode;
qs_output.settled = qs_state.settled;
qs_output.error_angle_rad = angle;
qs_output.applied_step_rad = step;
qs_output.commanded_rate_rad_cycle = qs_state.commanded_rate_rad_cycle;
qs_output.braking_rate_rad_cycle = braking;
qs_output.command_q_bi = q_cmd;
qs_output.slew_axis = axis;
qs_output.reversal_reset = reversal;

