        new_rate -= qs_config.max_accel_rad_cycle2;
        if (new_rate < target_rate) new_rate = target_rate;
    } else {
        new_rate = target_rate;
    }
    if (new_rate < 0.0) new_rate = 0.0;

    /* mode判定：上升=ACCEL，下降=DECEL，持平（含触顶巡航）=CRUISE */
    if (new_rate > prev_rate) {
        qs_state.mode = QS_ACCEL;
    } else if (new_rate < prev_rate) {
        qs_state.mode = QS_DECEL;
    } else {
        qs_state.mode = QS_CRUISE;
    }
    qs_state.commanded_rate_rad_cycle = new_rate;
}

if (angle <= 0.0) {
    step = 0.0;
} else {
    step = new_rate;
    if (angle < step) step = angle;
}
applied = step;

qs_output.applied_step_rad = applied;
qs_output.error_angle_rad = angle;
qs_output.commanded_rate_rad_cycle = new_rate;

if (angle > 0.0) {
    qs_state.previous_axis = axis;
    qs_state.axis_valid = 1;
}

if ((angle <= qs_config.settle_angle_rad) &&
    (new_rate <= qs_config.settle_rate_rad_cycle)) {
    qs_state.settled += 1U;
    if (qs_state.settled >= qs_config.settle_cycles) {
        qs_state.mode = QS_HOLD;
    } else {
        qs_state.mode = QS_SETTLE;
    }
} else {
    qs_state.settled = 0U;
}

if ((applied > 0.0) && (sin_half > ADCS_EPS_NORM)) {
    double half = 0.5 * applied;
    double s = sin(half);
    adcs_quat_t dq;
    dq.w = cos(half);
    dq.x = s * axis.x;
    dq.y = s * axis.y;
    dq.z = s * axis.z;
    cmdq = adcs_quat_multiply(&dq, &cur);
    (void)adcs_quat_normalize(&cmdq, &cmdq);
} else {
    cmdq = cur;
}
qs_output.command_q_bi = cmdq;

qs_output.mode = qs_state.mode;
qs_output.settled = qs_state.settled;
qs_output.slew_axis = qs_state.previous_axis;
